CREATE TABLE IF NOT EXISTS combo_indicator_config (
    indicator_code      VARCHAR(100)  PRIMARY KEY,
    display_name        VARCHAR(200)  NOT NULL,
    category            VARCHAR(50)   NOT NULL,
    hint_type           VARCHAR(30)   NOT NULL,
    family_type         VARCHAR(30)   NOT NULL,
    base_difficulty     INTEGER       NOT NULL DEFAULT 50 CHECK (base_difficulty >= 1 AND base_difficulty <= 100),
    quality_score       DECIMAL(3, 2) NOT NULL DEFAULT 0.80 CHECK (quality_score >= 0 AND quality_score <= 1),
    max_ambiguity_count INTEGER,
    is_active           BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_combo_indicator_config_active ON combo_indicator_config (is_active);

CREATE TABLE IF NOT EXISTS combo_indicator_component (
    indicator_code      VARCHAR(100) NOT NULL,
    component_key       VARCHAR(50)  NOT NULL,
    stat_source         VARCHAR(30)  NOT NULL,
    stat_indicator_code VARCHAR(100) NOT NULL,
    formatter           VARCHAR(30)  NOT NULL DEFAULT 'AUTO',
    required            BOOLEAN      NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_combo_indicator_component PRIMARY KEY (indicator_code, component_key),
    CONSTRAINT fk_combo_indicator_component_config
        FOREIGN KEY (indicator_code) REFERENCES combo_indicator_config (indicator_code) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_combo_indicator_component_source ON combo_indicator_component (stat_source, stat_indicator_code);

CREATE TABLE IF NOT EXISTS combo_indicator_predicate (
    indicator_code      VARCHAR(100) NOT NULL,
    predicate_order     INTEGER      NOT NULL,
    left_component_key  VARCHAR(50)  NOT NULL,
    operator            VARCHAR(20)  NOT NULL,
    comparison_mode     VARCHAR(20)  NOT NULL DEFAULT 'CONSTANT',
    right_value_numeric NUMERIC(20, 4),
    right_component_key VARCHAR(50),
    CONSTRAINT pk_combo_indicator_predicate PRIMARY KEY (indicator_code, predicate_order),
    CONSTRAINT fk_combo_indicator_predicate_config
        FOREIGN KEY (indicator_code) REFERENCES combo_indicator_config (indicator_code) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS combo_text_variant (
    indicator_code VARCHAR(100) NOT NULL,
    variant_no     INTEGER      NOT NULL,
    template       TEXT         NOT NULL,
    CONSTRAINT pk_combo_text_variant PRIMARY KEY (indicator_code, variant_no),
    CONSTRAINT fk_combo_text_variant_config
        FOREIGN KEY (indicator_code) REFERENCES combo_indicator_config (indicator_code) ON DELETE CASCADE
);

ON CONFLICT (indicator_code) DO UPDATE
    SET display_name        = EXCLUDED.display_name,
        category            = EXCLUDED.category,
        hint_type           = EXCLUDED.hint_type,
        family_type         = EXCLUDED.family_type,
        base_difficulty     = EXCLUDED.base_difficulty,
        quality_score       = EXCLUDED.quality_score,
        max_ambiguity_count = EXCLUDED.max_ambiguity_count,
        is_active           = TRUE,
        updated_at          = CURRENT_TIMESTAMP;

ON CONFLICT (indicator_code, component_key) DO UPDATE
    SET stat_source         = EXCLUDED.stat_source,
        stat_indicator_code = EXCLUDED.stat_indicator_code,
        formatter           = EXCLUDED.formatter,
        required            = EXCLUDED.required;

ON CONFLICT (indicator_code, predicate_order) DO UPDATE
    SET left_component_key  = EXCLUDED.left_component_key,
        operator            = EXCLUDED.operator,
        comparison_mode     = EXCLUDED.comparison_mode,
        right_value_numeric = EXCLUDED.right_value_numeric,
        right_component_key = EXCLUDED.right_component_key;

ON CONFLICT (indicator_code, variant_no) DO UPDATE
    SET template = EXCLUDED.template;
